        "a.proto" => "syntax = \"proto3\";\nmessage Foo {\n  int32 a = 1 [default = 5];\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:3:26: Explicit default values are not allowed in proto3."
      ]
    },
    "alias without allow_alias" => {
      files: {
        "a.proto" => "syntax = \"proto2\";\nenum E {\n  A = 1;\n  B = 1;\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:4:7: \"B\" uses the same enum value as \"A\". If this is intended, set 'option allow_alias = true;' to the enum definition. The next available enum value is 2."
      ]
    },
    "allow_alias false" => {
      files: {
        "a.proto" => "syntax = \"proto2\";\nenum E {\n  option allow_alias = false;\n  A = 1;\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:6:1: \"E\" declares 'option allow_alias = false;' which has no effect. Please remove the declaration."
      ]
    },
    "allow_alias without aliases" => {
      files: {
        "a.proto" => "syntax = \"proto2\";\nenum E {\n  option allow_alias = true;\n  A = 1;\n  B = 2;\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:7:1: \"E\" declares support for enum aliases but no enum values share field numbers. Please remove the unnecessary 'option allow_alias = true;' declaration."
      ]
    },
    "enum without values" => {
      files: {
        "a.proto" => "syntax = \"proto2\";\nenum E {}\n"
      },
      success: false,
      protoc: [
        "a.proto:2:6: Enums must contain at least one value."
      ]
    },
    "method input is an enum" => {
      files: {
        "a.proto" => "syntax = \"proto3\";\nenum E { Z = 0; }\nmessage M {}\nservice S {\n  rpc Do(E) returns (M);\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:5:10: \"E\" is not a message type."
      ]
    },
    "method output undefined" => {
      files: {
        "a.proto" => "syntax = \"proto3\";\nmessage M {}\nservice S {\n  rpc Do(M) returns (Nope);\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:4:22: \"Nope\" is not defined."
      ]
    },
    "duplicate method" => {
      files: {
        "a.proto" => "syntax = \"proto3\";\nmessage M {}\nservice S {\n  rpc Do(M) returns (M);\n  rpc Do(M) returns (M);\n}\n"
      },
      success: false,
      protoc: [
        "a.proto:5:7: \"Do\" is already defined in \"S\"."
      ]
    },
