    "message option without aggregate" => {
      files: {
        "a.proto" => "syntax = \"proto2\";\nimport \"google/protobuf/descriptor.proto\";\nmessage Opt { optional int32 a = 1; }\nextend google.protobuf.FileOptions {\n  optional Opt opt = 50000;\n}\noption (opt) = 3;\n"
