      files: {
        "a.proto" => "syntax = \"proto2\";\nimport \"google/protobuf/descriptor.proto\";\nextend google.protobuf.FieldOptions {\n  optional int32 only_files = 50000 [targets = TARGET_TYPE_FILE];\n}\nmessage M {\n  optional int32 a = 1 [(only_files) = 3];\n}\n"
