        "a.proto:4:9: Field name CamelField should be lower_snake_case (features.enforce_naming_style = STYLE_LEGACY can be used to opt out of this check)",
        "a.proto:6:6: Enum name my_enum should be TitleCase (features.enforce_naming_style = STYLE_LEGACY can be used to opt out of this check)",
